#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const long long MOD = 1000000007;

struct Matrix {
    int data[31][31], size;
    Matrix operator*(const Matrix &other) const {
        Matrix result; result.size = size;
        for (int i = 0; i <= size; ++i)
            for (int j = 0; j <= size; ++j) {
                result.data[i][j] = 0;
                for (int k = 0; k <= size; ++k)
                    result.data[i][j] = ((long long)data[i][k] * other.data[k][j] + result.data[i][j]) % MOD;
            }
        return result;
    }
};

int main() {
    long long N, K;
    scanf("%lld %lld", &N, &K);
    int digits[70], count = 0;
    while (N != 0) {
        digits[count++] = N % K;
        N /= K;
    }

    static Matrix baseMatrices[64][30], prefixMatrices[64][30], suffixMatrices[64][30], finalAnswer;
    for (int i = 0; i < K; ++i) {
        for (int j = 0; j <= K; ++j) {
            baseMatrices[0][i].data[j][j] = 1;
            baseMatrices[0][i].data[j][i] = 1;
        }
        baseMatrices[0][i].size = K;
    }

    prefixMatrices[0][0] = baseMatrices[0][0];
    suffixMatrices[0][K - 1] = baseMatrices[0][K - 1];

    for (int i = 1; i < K; ++i)
        prefixMatrices[0][i] = prefixMatrices[0][i - 1] * baseMatrices[0][i];

    for (int i = K - 2; i >= 0; --i)
        suffixMatrices[0][i] = baseMatrices[0][i] * suffixMatrices[0][i + 1];

    for (int i = 1; i < count; ++i) {
        baseMatrices[i][0] = suffixMatrices[i - 1][0];
        for (int j = 1; j < K; ++j)
            baseMatrices[i][j] = suffixMatrices[i - 1][j] * prefixMatrices[i - 1][j - 1];

        prefixMatrices[i][0] = baseMatrices[i][0];
        suffixMatrices[i][K - 1] = baseMatrices[i][K - 1];

        for (int j = 1; j < K; ++j)
            prefixMatrices[i][j] = prefixMatrices[i][j - 1] * baseMatrices[i][j];

        for (int j = K - 2; j >= 0; --j)
            suffixMatrices[i][j] = baseMatrices[i][j] * suffixMatrices[i][j + 1];
    }

    finalAnswer.data[0][K] = 1;
    finalAnswer.size = K;
    finalAnswer = finalAnswer * prefixMatrices[count - 1][digits[count - 1] - 1];

    int lastDigit = digits[count - 1];
    for (int i = count - 2; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j)
            finalAnswer = finalAnswer * baseMatrices[i][(j + lastDigit) % K];
        lastDigit += digits[i];
    }

    long long totalSum = 0;
    for (int i = 0; i <= K; ++i)
        totalSum += finalAnswer.data[0][i];

    printf("%lld\n", totalSum % MOD);
    return 0;
}
